CREATE FUNCTION direct_service_probe(phase_name text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE n text; pk text; seed jsonb; one_count bigint; before_data jsonb; outcome text;
BEGIN
 FOREACH n IN ARRAY ARRAY['stg_jonathan_whiteny_biopsies','import_logs','mprf_manta_map','mprf_sighting_map','photos_filenames_cleaned_integer_ids'] LOOP
  before_data:=target_snapshot(); outcome:='00000';
  pk:=CASE n WHEN 'stg_jonathan_whiteny_biopsies' THEN 'No' WHEN 'import_logs' THEN 'id' WHEN 'mprf_manta_map' THEN 'pk_mprf_manta_id' WHEN 'mprf_sighting_map' THEN 'pk_mprf_sighting_id' ELSE 'pk_photo_id' END;
  BEGIN
   SET LOCAL ROLE service_role;
   EXECUTE format('SELECT count(*) FROM public.%I',n) INTO one_count;
   PERFORM assert_ok(one_count>0,phase_name||' direct service SELECT '||n);
   EXECUTE format('SELECT to_jsonb(t) FROM public.%I t LIMIT 1',n) INTO seed;
   seed:=seed||jsonb_build_object(pk,CASE WHEN n='mprf_sighting_map' THEN to_jsonb('SYNTHETIC-DIFFERENTIAL'::text) ELSE to_jsonb(900001) END);
   EXECUTE format('INSERT INTO public.%I SELECT * FROM jsonb_populate_record(NULL::public.%I,$1)',n,n) USING seed;
   GET DIAGNOSTICS one_count=ROW_COUNT;
   PERFORM assert_ok(one_count=1,phase_name||' direct service INSERT '||n);
   EXECUTE format('UPDATE public.%I SET %I=%I WHERE %I::text=$1',n,pk,pk,pk) USING seed->>pk;
   GET DIAGNOSTICS one_count=ROW_COUNT;
   PERFORM assert_ok(one_count=1,phase_name||' direct service UPDATE '||n);
   EXECUTE format('DELETE FROM public.%I WHERE %I::text=$1',n,pk) USING seed->>pk;
   GET DIAGNOSTICS one_count=ROW_COUNT;
   PERFORM assert_ok(one_count=1,phase_name||' direct service DELETE '||n);
   RAISE EXCEPTION USING ERRCODE='Z0001';
  EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL; WHEN OTHERS THEN outcome:=SQLSTATE; END;
  RESET ROLE;
  PERFORM assert_ok(outcome='00000',phase_name||' service DML no permission failure '||n);
  PERFORM assert_ok(target_snapshot()=before_data,phase_name||' service DML leaves no mutation '||n);
 END LOOP;
END $$;
SELECT check_interfaces('forward');
SELECT direct_service_probe('forward');
